// Semantic ranks are computed from normalized MiniLM embeddings at build time.
import { vocabulary, targets, encodedRanks } from './semantic-data.js';
export { vocabulary, targets };
const words=new Set(vocabulary), rankCache=new Map();
export function ranking(target){if(!targets.includes(target))throw Error('Unknown semantic puzzle.');if(!rankCache.has(target)){const raw=atob(encodedRanks[targets.indexOf(target)]);const ranks=vocabulary.map((word,i)=>({word,rank:raw.charCodeAt(i*2)|(raw.charCodeAt(i*2+1)<<8)}));rankCache.set(target,new Map(ranks.map(x=>[x.word,x.rank])));}return rankCache.get(target);}
export function feedback(rank){return rank===1?'Found it!':rank<=10?'Burning hot':rank<=100?'Hot':rank<=500?'Warm':rank<=1500?'Cool':'Cold';}
export function createSemantic(target,id){if(!targets.includes(target))throw Error('Unknown semantic puzzle.');return {id,target,guesses:[],draft:'',hints:0,complete:false};}
export function submitSemantic(game,raw){const word=raw.trim().toLowerCase();if(game.complete)throw Error('This puzzle is already solved.');if(!words.has(word))throw Error('Not in this word pack. Try another single word.');if(game.guesses.includes(word))throw Error('You already guessed that word.');game.guesses.push(word);game.draft='';game.complete=word===game.target;return ranking(game.target).get(word);}
export function emptySemantic(){return {current:null,history:[]};}
export function validateSemantic(box){if(box===undefined)return emptySemantic();if(!box||!Array.isArray(box.history)||box.history.length>10000)throw Error('Invalid semantic history.');for(const h of box.history)if(!h||typeof h.id!=='string'||h.id.length>80||!/^\d{4}-\d{2}-\d{2}$/.test(h.date)||!Number.isInteger(h.hints)||h.hints<0||h.hints>vocabulary.length)throw Error('Invalid semantic result.');const g=box.current;if(g!==null){if(!g||typeof g.id!=='string'||g.id.length>80||!targets.includes(g.target)||!Array.isArray(g.guesses)||g.guesses.length>vocabulary.length||new Set(g.guesses).size!==g.guesses.length||g.guesses.some(w=>!words.has(w))||typeof g.draft!=='string'||!/^[a-z]{0,20}$/.test(g.draft)||!Number.isInteger(g.hints)||g.hints<0||g.hints>g.guesses.length||typeof g.complete!=='boolean'||g.complete!==(g.guesses.at(-1)===g.target)||g.guesses.slice(0,-1).includes(g.target))throw Error('Invalid semantic puzzle.');}return {current:g,history:box.history.map(h=>({id:h.id,date:h.date,hints:h.hints}))};}
